actions.script:
if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.monitor.MonitorServices.receive#BrowserTelemetry')
            .parameters({signal: 'traces', bodyText: ec.web.parameters._requestBodyText || ''}).disableAuthz().call()
    if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(400, errors) }
    else ec.web.sendJsonResponse(out && out.rejected ? {partialSuccess: {rejectedSpans: String(out.rejected)}} : {})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    const out = ec.service.sync().name('org.moqui.monitor.MonitorServices.receive#BrowserTelemetry')
            .parameters({signal: 'logs', bodyText: ec.web.parameters._requestBodyText || ''}).disableAuthz().call()
    if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(400, errors) }
    else ec.web.sendJsonResponse(out && out.rejected ? {partialSuccess: {rejectedLogRecords: String(out.rejected)}} : {})
}

if (!ec.user.userId) { ec.web.sendJsonError(401, 'Authentication required') } else {
    ec.service.sync().name('org.moqui.monitor.MonitorServices.receive#BrowserReplay')
            .parameters({bodyText: ec.web.parameters._requestBodyText || ''}).disableAuthz().call()
    if (ec.message.hasError()) { const errors = ec.message.errorsString; ec.message.clearErrors(); ec.web.sendJsonError(413, errors) }
    else ec.web.sendJsonResponse({})
}
